        },
        {
          question: "Why do cats knead blankets and laps?",
          answer:
            "Kneading is a behavior that starts in kittenhood while nursing and often carries into adulthood as a sign of comfort. Many cats knead when they feel content, safe, or ready to settle down for a nap."
        }
      ];

      function Hero() {
        return `
          <section class="hero" aria-labelledby="page-title">
            <p class="eyebrow">Cat care guide</p>
            <h1 id="page-title">Frequently asked cat questions</h1>
            <p>
              Explore quick answers about feline habits, health basics, and everyday behavior.
              Each topic starts collapsed so you can open only what you want to read.
            </p>
          </section>
        `;
      }

      function FAQItem(item, index) {
        const panelId = `faq-panel-${index}`;
        const buttonId = `faq-button-${index}`;

        return `
          <div class="example">
            <button
              id="${buttonId}"
              class="question-button"
              type="button"
              aria-expanded="false"
              aria-controls="${panelId}"
            >
              <span>${item.question}</span>
              <span class="indicator" aria-hidden="true">+</span>
