      function FAQList(items) {
        return `
          <section class="faq-grid" aria-label="Cat frequently asked questions">
            ${items.map(FAQItem).join("")}
          </section>
        `;
      }

      function App() {
        return `
          ${Hero()}
          ${FAQList(faqItems)}
        `;
      }

      function render() {
        const root = document.getElementById("main-content");
        root.innerHTML = App();

